20	//
21	// 当前时刻为 2026-04-01 00:00 时，一月、二月均已到期，三月尚未到期。
22	
23	// multiBillFixture 构造上述账户：一月初开通的持续订阅，并在时钟拨到
24	// 四月一日零点后补齐一、二、三月三张账单。
25	func multiBillFixture(t *testing.T) (*Service, *fakeClock) {
26		t.Helper()
27		s, clk := newTestService(utc(2026, 1, 1, 0, 0))
28		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
29		mustAccount(t, s, "a")
30		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
31			t.Fatalf("subscribe: %v", err)
32		}
33	
34		clk.t = utc(2026, 4, 1, 0, 0)
35		for _, m := range []Month{jan(2026), feb(2026), mar(2026)} {
36			b, err := s.CreateBill("a", m)
37			if err != nil {
38				t.Fatalf("create bill %s: %v", m, err)
39			}
40			if b.TotalDue != 1000 || b.Tax != 0 || b.Balance != 1000 || b.Paid != 0 || b.Settled {
41				t.Fatalf("bill %s initial state: %+v", m, b)
42			}
43		}
44		return s, clk
45	}
46	
47	// wantBill 检查指定账单的付款状态，以及出账时即固定的应付总额、税额、
48	// 用量明细与截止时刻。
49	func wantBill(t *testing.T, s *Service, period Month, dueAt time.Time, paid, balance int64, settled bool) {
50		t.Helper()
51		b, err := s.GetBill("a", period)
52		if err != nil {
53			t.Fatalf("get bill %s: %v", period, err)
54		}
55		if b.Paid != paid || b.Balance != balance || b.Settled != settled {
56			t.Fatalf("bill %s payment state: paid=%d balance=%d settled=%v, want paid=%d balance=%d settled=%v",
57				period, b.Paid, b.Balance, b.Settled, paid, balance, settled)
58		}
59		// 金额与用量明细保持出账时的值，不随后续付款变化。
60		if b.TotalDue != 1000 || b.MonthlyFee != 1000 || b.OverageFee != 0 || b.Tax != 0 {
61			t.Fatalf("bill %s amounts changed: %+v", period, b)
62		}
63		if b.TotalUsage != 0 || b.IncludedUnits != 0 || b.OverageUnits != 0 {
64			t.Fatalf("bill %s usage detail changed: %+v", period, b)
65		}
