70	
71	func wantSuspended(t *testing.T, s *Service, want bool) AccountStatus {
72		t.Helper()
73		st, err := s.Status("a")
74		if err != nil {
75			t.Fatalf("status: %v", err)
76		}
77		if st.Suspended != want {
78			t.Fatalf("suspended = %v, want %v; bills: %+v", st.Suspended, want, st.Bills)
