81	}
82	
83	func TestSuspensionMultipleBillsIndependentPayments(t *testing.T) {
84		s, clk := multiBillFixture(t)
85	
86		janDue := utc(2026, 2, 8, 0, 0)
87		febDue := utc(2026, 3, 8, 0, 0)
88		marDue := utc(2026, 4, 8, 0, 0)
89	
90		// 四月一日零点：一月、二月已到期欠费，三月未到期；账户停用，订阅仍有效。
91		st := wantSuspended(t, s, true)
92		if !st.Subscribed {
93			t.Fatalf("subscription must remain active while suspended: %+v", st)
94		}
95		if st.CurrentTerms.MonthlyFee != 1000 || st.CurrentTerms.PlanID != "p" {
96			t.Fatalf("current terms changed: %+v", st.CurrentTerms)
97		}
98	
99		// 即使用量发生在有效订阅期间、所属四月尚未出账，停用期间也必须拒绝。
100		aprEvent := Event{AccountID: "a", EventID: "evt-apr", At: utc(2026, 4, 1, 0, 0), Quantity: 4}
101		if _, err := s.RecordEvent(aprEvent); !errors.Is(err, ErrSuspended) {
102			t.Fatalf("apr event while suspended: %v", err)
103		}
104		// 被拒绝的用量不增加当月累计量。
105		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 0 {
106			t.Fatalf("apr usage after rejection = %d, want 0", u.Total)
107		}
108	
109		// 先向二月账单登记 300：只改变二月本身，一月、三月不受影响，继续停用。
110		r, err := s.RecordPayment("a", "pay-feb-1", feb(2026), 300)
111		if err != nil || !r.Registered || r.BillBalance != 700 || r.Settled {
112			t.Fatalf("feb partial payment: %+v %v", r, err)
113		}
114		wantBill(t, s, jan(2026), janDue, 0, 1000, false)
115		wantBill(t, s, feb(2026), febDue, 300, 700, false)
116		wantBill(t, s, mar(2026), marDue, 0, 1000, false)
117		wantSuspended(t, s, true)
118	
119		// 再付清一月：二月仍欠 700 且已到期，账户必须继续停用。
120		// 付清一月没有替二月还款。
121		if r, err := s.RecordPayment("a", "pay-jan", jan(2026), 1000); err != nil ||
122			!r.Registered || r.BillBalance != 0 || !r.Settled {
123			t.Fatalf("jan payment in full: %+v %v", r, err)
124		}
125		wantBill(t, s, jan(2026), janDue, 1000, 0, true)
126		wantBill(t, s, feb(2026), febDue, 300, 700, false)
127		wantSuspended(t, s, true)
128		// 停用仍生效：四月新用量继续被拒。
129		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-blocked", At: utc(2026, 4, 1, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
130			t.Fatalf("event with jan settled but feb overdue: %v", err)
131		}
132	
133		// 结清二月剩余 700：到期账单全部付清，账户立即恢复；
134		// 三月仍欠 1000 但截止时刻（四月八日）未到，不阻止恢复。
135		if r, err := s.RecordPayment("a", "pay-feb-2", feb(2026), 700); err != nil ||
136			!r.Registered || r.BillBalance != 0 || !r.Settled {
137			t.Fatalf("feb final payment: %+v %v", r, err)
138		}
139		st = wantSuspended(t, s, false)
140		if !st.Subscribed {
141			t.Fatalf("subscription must remain active after recovery: %+v", st)
142		}
143		wantBill(t, s, jan(2026), janDue, 1000, 0, true)
144		wantBill(t, s, feb(2026), febDue, 1000, 0, true)
145		wantBill(t, s, mar(2026), marDue, 0, 1000, false)
146	
147		// Status 的账单摘要按账期排列并反映各账期独立的付款结果。
148		if len(st.Bills) != 3 {
149			t.Fatalf("status bills = %+v", st.Bills)
150		}
151		wantSummary := []struct {
152			period        Month
153			paid, balance int64
154			settled       bool
155		}{
156			{jan(2026), 1000, 0, true},
157			{feb(2026), 1000, 0, true},
158			{mar(2026), 0, 1000, false},
159		}
160		for i, w := range wantSummary {
161			got := st.Bills[i]
162			if got.Period != w.period || got.TotalDue != 1000 || got.Paid != w.paid ||
163				got.Balance != w.balance || got.Settled != w.settled || !got.DueAt.Equal(w.period.End().AddDate(0, 0, 7)) {
164				t.Fatalf("status bills[%d] = %+v, want %+v", i, got, w)
165			}
166		}
167	
168		// 结清到期欠款后，停用期间被拒的同一事件以相同内容再次提交应被首次接收，
169		// 且只增加这一个事件的数量（证明此前被拒不占用事件标识、不累计用量）。
170		r2, err := s.RecordEvent(aprEvent)
171		if err != nil || !r2.Accepted || r2.Period != apr(2026) {
172			t.Fatalf("apr event re-submitted after recovery: %+v %v", r2, err)
173		}
174		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 4 {
175			t.Fatalf("apr usage = %d, want 4 (rejected attempt must not count)", u.Total)
176		}
177		// 再报同一条为去重重报，不重复累计。
178		if r3, err := s.RecordEvent(aprEvent); err != nil || r3.Accepted {
179			t.Fatalf("identical replay accumulates again: %+v %v", r3, err)
180		}
181		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 4 {
182			t.Fatalf("apr usage after replay = %d, want 4", u.Total)
183		}
184	
185		// 三月账单仍有余额，但四月八日零点前账户保持可接收新用量。
186		clk.t = utc(2026, 4, 7, 23, 59)
187		wantSuspended(t, s, false)
188		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr-2", At: utc(2026, 4, 7, 23, 59), Quantity: 5}); err != nil {
189			t.Fatalf("event just before mar due: %v", err)
190		}
191		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 9 {
192			t.Fatalf("apr usage = %d, want 9", u.Total)
193		}
194	
195		// 恰到三月截止时刻：无需先发生其他业务操作，Status 即显示重新停用。
196		clk.t = utc(2026, 4, 8, 0, 0)
197		st = wantSuspended(t, s, true)
198		if !st.Subscribed {
199			t.Fatalf("subscription must still be active at mar due time: %+v", st)
200		}
201		// 停用再次拒绝新增用量；被拒用量不增加累计、不占用标识（同路径规则）。
202		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr-3", At: utc(2026, 4, 8, 0, 0), Quantity: 2}); !errors.Is(err, ErrSuspended) {
203			t.Fatalf("event exactly at mar due: %v", err)
204		}
205		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 9 {
206			t.Fatalf("apr usage = %d after due rejection, want 9", u.Total)
207		}
208		// 一月、二月已结清状态不被三月到期影响。
209		wantBill(t, s, jan(2026), janDue, 1000, 0, true)
210		wantBill(t, s, feb(2026), febDue, 1000, 0, true)
211		wantBill(t, s, mar(2026), marDue, 0, 1000, false)
212	}
213	
214	// TestSuspensionRecoveryOrderIndependent 反向付款顺序：先全额付清二月、
215	// 再付清一月，恢复规则必须与先付一月一致——只要仍有一张到期账单有余额，
216	// 就不能因付款顺序而提前恢复；未到期的三月同样不参与判定。
217	func TestSuspensionRecoveryOrderIndependent(t *testing.T) {
218		s, _ := multiBillFixture(t)
219	
220		// 两张到期账单并存：先付清二月，一月仍到期欠费，不能恢复。
221		if r, err := s.RecordPayment("a", "pay-feb", feb(2026), 1000); err != nil ||
222			!r.Registered || r.BillBalance != 0 || !r.Settled {
223			t.Fatalf("feb paid first: %+v %v", r, err)
224		}
225		wantBill(t, s, jan(2026), utc(2026, 2, 8, 0, 0), 0, 1000, false)
226		wantBill(t, s, feb(2026), utc(2026, 3, 8, 0, 0), 1000, 0, true)
227		wantSuspended(t, s, true)
228		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr", At: utc(2026, 4, 1, 0, 0), Quantity: 4}); !errors.Is(err, ErrSuspended) {
229			t.Fatalf("event with only jan overdue: %v", err)
230		}
231	
232		// 再付清一月：到期账单全部结清，立即恢复；三月未到期不阻止。
233		if r, err := s.RecordPayment("a", "pay-jan", jan(2026), 1000); err != nil ||
234			!r.Registered || r.BillBalance != 0 || !r.Settled {
235			t.Fatalf("jan paid second: %+v %v", r, err)
236		}
237		st := wantSuspended(t, s, false)
238		if !st.Subscribed {
239			t.Fatalf("subscription must remain active: %+v", st)
240		}
241		wantBill(t, s, mar(2026), utc(2026, 4, 8, 0, 0), 0, 1000, false)
242	
243		// 恢复后四月用量可被首次接收（此前被拒不累计、不占标识）。
244		if r2, err := s.RecordEvent(Event{AccountID: "a", EventID: "evt-apr", At: utc(2026, 4, 1, 0, 0), Quantity: 4}); err != nil ||
245			!r2.Accepted || r2.Period != apr(2026) {
246			t.Fatalf("apr event after reverse-order recovery: %+v %v", r2, err)
247		}
248		if u, _ := s.MonthlyUsage("a", apr(2026)); u.Total != 4 {
249			t.Fatalf("apr usage = %d, want 4", u.Total)
250		}
251	}
