472		s, _ := newTestService(utc(2026, 2, 1, 0, 0))
473		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
474		mustAccount(t, s, "a")
475		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
476			t.Fatal(err)
477		}
478		if _, err := s.CreateBill("a", jan(2026)); err != nil {
479			t.Fatal(err)
480		}
481		if _, err := s.RecordPayment("a", "p1", jan(2026), 1000); err != nil {
482			t.Fatal(err)
483		}
484		// 原账单已结清：相同标识改金额仍是冲突，不能当作新付款。
485		if _, err := s.RecordPayment("a", "p1", jan(2026), 1); !errors.Is(err, ErrPaymentConflict) {
486			t.Fatalf("amount conflict on settled bill: %v", err)
487		}
488		// 改指向尚无账单的账期：仍是冲突而非 ErrBillNotFound。
489		if _, err := s.RecordPayment("a", "p1", feb(2026), 1); !errors.Is(err, ErrPaymentConflict) {
490			t.Fatalf("period conflict to missing bill: %v", err)
491		}
492		// 完全相同的重报即使原金额已超过当前余额（当前为 0）仍成功，且不再加已付。
493		r, err := s.RecordPayment("a", "p1", jan(2026), 1000)
